package com.tend.native

import android.content.Context
import androidx.core.content.pm.ShortcutInfoCompat
import androidx.core.content.pm.ShortcutManagerCompat
import androidx.core.graphics.drawable.IconCompat
import com.tend.nativeplugin.R

/**
 * Launcher long-press shortcuts: "Quick add" (the native dialog, no app needed) and "Today".
 * Published from the plugin rather than a static shortcuts.xml, because the launcher activity's
 * manifest is generated by Tauri.
 */
object TendShortcuts {
  fun publish(context: Context) {
    val ctx = context.applicationContext
    try {
      val quick = ShortcutInfoCompat.Builder(ctx, "quick_add")
        .setShortLabel("Quick add")
        .setLongLabel("Add a reminder")
        .setIcon(IconCompat.createWithResource(ctx, R.drawable.ic_tend_shortcut_add))
        .setIntent(QuickAddActivity.intent(ctx))
        .build()
      val list = mutableListOf(quick)
      TendNotifications.launchIntent(ctx, TendIds.LAUNCH_OPEN, null)?.let { open ->
        list.add(
          ShortcutInfoCompat.Builder(ctx, "today")
            .setShortLabel("Today")
            .setLongLabel("Today's list")
            .setIcon(IconCompat.createWithResource(ctx, R.drawable.ic_tend_shortcut_today))
            .setIntent(open)
            .build()
        )
      }
      ShortcutManagerCompat.setDynamicShortcuts(ctx, list)
    } catch (e: Exception) {
      // Rate-limited or unsupported launcher: shortcuts are a nicety.
    }
  }
}
